import sys


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    w = [int(x) for x in data[1:1 + n]]
    edges = []
    idx = 1 + n
    for _ in range(n - 1):
        a = int(data[idx]) - 1
        b = int(data[idx + 1]) - 1
        idx += 2
        edges.append((a, b))
    best = 0
    for mask in range(1 << n):
        ok = True
        for a, b in edges:
            if (mask >> a) & 1 and (mask >> b) & 1:
                ok = False
                break
        if not ok:
            continue
        s = 0
        for i in range(n):
            if (mask >> i) & 1:
                s += w[i]
        if s > best:
            best = s
    print(best)


main()
